select '20000000-0000-0000-0000-000000000001',case when n%3=0 then '00000000-0000-0000-0000-000000000002'::uuid else '00000000-0000-0000-0000-000000000001'::uuid end,now()-(n||' hours')::interval,case n%5 when 0 then 'Payoneer — NovaTech Inc' when 1 then 'Wise — Figma Subscription' when 2 then 'Bank — LESCO Electricity' when 3 then 'Fiverr — Pixel Works' else 'Unknown merchant — QT*4471' end,case n%5 when 0 then 9620000 when 1 then 320000 when 2 then 840000 when 3 then 6000000 else 184000 end,'PKR',case when n%5 in(0,3) then 'credit'::public.transaction_direction else 'debit'::public.transaction_direction end,case n%5 when 0 then 'payoneer'::public.account_provider when 1 then 'wise'::public.account_provider when 2 then 'bank_sms'::public.account_provider when 3 then 'fiverr'::public.account_provider else 'bank_sms'::public.account_provider end,'seed-'||n,case n%5 when 0 then '10000000-0000-0000-0000-000000000001'::uuid when 1 then '10000000-0000-0000-0000-000000000003'::uuid when 2 then '10000000-0000-0000-0000-000000000002'::uuid when 3 then '10000000-0000-0000-0000-000000000001'::uuid else null end,case when n%5=4 then 'low'::public.transaction_confidence else 'high'::public.transaction_confidence end,case when n%5=4 then 'review'::public.transaction_status else 'ok'::public.transaction_status end from generate_series(1,15)n;
